function getQueryVariable(e) {
  for (var o = window.location.search.substring(1).split(/[?&]/), t = 0; t < o.length; t++) {
    var r = o[t].split("=");
    if (r[0] == e) {
      return "Qv" == r[0] ? o[t].substr(3, o[t].length) : r[1];
    }
  }
  return "";
}

function redirectTo(e) {
  var o = window.location.protocol + "//" + window.location.hostname + "/guest/register/oauth/" + e + window.location.search;
  window.location = o;
}

function getFormAction(e) {
  var o = getQueryVariable("cps"),
    t = getQueryVariable("type"),
    r = {
      action: "/cgi-bin/hslogin.cgi",
      method: "POST"
    };

  if ("iden" == t || "nac" == t) {
    r.action = "reg" == e ? "../process.php" : "../authenticate.php";
    r.method = "GET";
  } else if ("" != o && "reg" == e) {
    r.action = window.location.protocol + "//" + window.location.host + "/splash/templates/register.php";
    r.method = "POST";
  } else {
    var i = ":" + ("https:" == window.location.protocol ? 444 : 880) + "/cgi-bin/hslogin.cgi";
    r.action = window.location.protocol + "//" + getQueryVariable("hs_server") + i;
    r.method = "POST";
  }
  return r;
}

function getLogoutURL() {
  var e = ":" + ("https:" == window.location.protocol ? 444 : 880) + "/cgi-bin/hslogout.cgi";
  return window.location.protocol + "//1.1.1.1" + e;
}

function URLSearchToFormFields() {
  var e = [],
    o = [],
    t = location.search.substr(1),
    r = {
      hsServer: "<input type='hidden' name='f_hs_server' value=''>",
      serHsServer: "f_hs_server=",
      qv: "<input type='hidden' name='f_Qv' value=''>",
      serQv: "f_Qv="
    };

  t = t.split("&");

  for (var i = 0, n = "", s = "", a = 0; a < t.length; a++) {
    i = t[a].search("=");
    n = t[a].substr(0, i);
    s = t[a].substr(i + 1);

    if ("Qv" != n && "f_Qv" != n) {
      if ("hs_server" != n && "f_hs_server" != n) {
        o.push(n + "=" + decodeURIComponent(s));
        e.push("<input type='hidden' name='" + n + "' value='" + decodeURIComponent(s) + "'>");
      } else {
        r.hsServer = "<input type='hidden' name='f_hs_server' value='" + s + "'>";
        r.serHsServer = "f_hs_server=" + s;
      }
    } else {
      r.qv = "<input type='hidden' name='f_Qv' value='" + s + "'>";
      r.serQv = "f_Qv=" + s;
    }
  }

  r.currTime = '<input name="f_curr_time" type="hidden" value="' + Math.floor((new Date).getTime() / 1e3) + '">';
  r.serCurrTime = "f_curr_time=" + Math.floor((new Date).getTime() / 1e3);
  r.formItems = e.join("");
  r.serialized = o.join("&");
  return r;
}